#include "IAiTaskService.hpp"
#include <chrono>
namespace luma::ai::task { std::string AiTaskService::Submit(core::AiRequest r){std::lock_guard l(mutex_);auto t=std::make_shared<AiTask>();t->id="ai-task-"+std::to_string(next_id_++);t->request=std::move(r);t->request.request_id=t->id;t->created_at_ms=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();tasks_[t->id]=t;queue_.push_back(t);return t->id;} bool AiTaskService::RunNext(){std::shared_ptr<AiTask>t;{std::lock_guard l(mutex_);if(queue_.empty())return false;t=queue_.front();queue_.pop_front();t->status=Status::Running;}if(!orchestrator_){t->response.error="orchestrator is unavailable";t->status=Status::Failed;return true;}t->response=orchestrator_->Execute(t->request);t->status=t->response.success?Status::Succeeded:Status::Failed;return true;} std::shared_ptr<const AiTask> AiTaskService::Get(const std::string&id)const{std::lock_guard l(mutex_);auto i=tasks_.find(id);return i==tasks_.end()?nullptr:i->second;} }
